// Conceptual representation of PKCE verification in Spring Security
public void verifyPkce(String codeVerifier, String storedChallenge) {
    String hashedVerifier = Base64.getUrlEncoder().withoutPadding()
        .encodeToString(MessageDigest.getInstance("SHA-256")
        .digest(codeVerifier.getBytes(StandardCharsets.US_ASCII)));

    if (!hashedVerifier.equals(storedChallenge)) {
        throw new OAuth2AuthorizationException("PKCE verification failed: Invalid code_verifier");
    }
}
